    hrows={r for r in rows if len(rows[r])>=2}
    vcols={c for c in cols if len(cols[c])>=2}
    eh={r:(min(c for rr,c in ms if rr==r),max(c for rr,c in ms if rr==r)) for r in hrows}
    ev={c:(min(r for rr,cc in ms if cc==c),max(r for rr,cc in ms if cc==c)) for c in vcols}
    cs=comps2(gi)
    # paint line cells only within extent between the outermost markers of that line
    paint=set(ms)
    for r in hrows:
        lo,hi=eh[r]
        for j in range(lo,hi+1): paint.add((r,j))
    for c in vcols:
        lo,hi=ev[c]
        for i in range(lo,hi+1): paint.add((i,c))
    for (a,b) in paint: g[a][b]=1
    for comp in cs:
        cells=set(comp); rs=[a for a,b in comp]; cls=[b for a,b in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
        hitH=any(r in hrows for r in range(r0,r1+1))
        hitV=any(c in vcols for c in range(c0,c1+1))
        if hitH and hitV:
            for (a,b) in cells: g[a][b]=1
        elif hitH:
            for (a,b) in cells:
                if r0<=a<=r1 and c0<=b<=c1: g[a][b]=1
        elif hitV:
            for (a,b) in cells:
                if r0<=a<=r1 and c0<=b<=c1: g[a][b]=1
    return g
