def comps(g, val=2):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and not seen[i][j]:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]==val and not seen[x][y]: st.append((x,y))
                out.append(set(comp))
    return out
