def f(gi):
    g=[row[:] for row in gi]; H,W=len(g),len(g[0])
    ms=[(i,j) for i in range(H) for j in range(W) if g[i][j]==1]
    hrows={r for r in range(H) if sum(1 for c in range(W) if g[r][c]==1)>=2}
    vcols={c for c in range(W) if sum(1 for r in range(H) if g[r][c]==1)>=2}
    for r in hrows:
        for j in range(W):
            if g[r][j]==0: g[r][j]=1
    for c in vcols:
        for i in range(H):
            if g[i][c]==0: g[i][c]=1
    cs=comps(gi)
    # painted cell sets
    painted=set()
    for r in hrows:
        for j in range(W): painted.add((r,j))
    for c in vcols:
        for i in range(H): painted.add((i,c))
    for comp in cs:
        for a,b in comp:
            if (a,b) in painted:
                for x,y in comp: g[x][y]=1
    return g
